"""TEST"""
import json
import re
import html
from pathlib import Path

BLOG = Path(__file__).resolve().parents[2] / "blog"
NAME = re.compile(r"^(\d{4}-\d{2}-\d{2})-.+\.html$")


def meta(text, name):
    for tag in re.findall(r"<meta\b[^>]*>", text, flags=re.I):
        n = re.search(r'name\s*=\s*["\']([^"\']*)["\']', tag, flags=re.I)
        if n and n.group(1).lower() == name:
            c = re.search(r'content\s*=\s*["\']([^"\']*)["\']', tag, flags=re.I)
            return html.unescape(c.group(1)).strip() if c else ""
    return ""


posts = []
for path in sorted(BLOG.glob("*.html")):
    m = NAME.match(path.name)
    if not m:
        continue  # skips index.html, etc
    text = path.read_text(encoding="utf-8")
    h1 = re.search(r"<h1[^>]*>(.*?)</h1>", text, flags=re.I | re.S)
    title = html.unescape(re.sub(r"<[^>]+>", "", h1.group(1))).strip() if h1 else path.stem
    tags = [t.strip() for t in meta(text, "tags").split(",") if t.strip()]
    posts.append({
        "file": path.name,
        "title": title,
        "date": m.group(1),
        "about": meta(text, "description"),
        "tags": tags,
    })

posts.sort(key=lambda p: (p["date"], p["file"]), reverse=True)

out = (
    "/* AUTO-GENERATED by .github/scripts/build_posts.py || Hi */\n"
    "window.POSTS = " + json.dumps(posts, indent=2, ensure_ascii=False) + ";\n"
)
(BLOG / "posts.js").write_text(out, encoding="utf-8")
print(f"Wrote {len(posts)} posts to {BLOG / 'posts.js'}")
